#include <stdio.h>
#include <string.h>

// Generated by deepseek, for testing pointer declarations and type qualifiers

int main() {
    // 定义一些测试数据
    char str1[] = "Hello";
    char str2[] = "World";
    char str3[] = "Test";
    const char cstr[] = "Constant";
    
    // 1. const char **p
    // 作用：p是一个指向指针的指针，指向的指针指向const char
    printf("\n1. const char **p 测试：\n");
    const char *cptr = cstr;  // 指向const char的指针
    const char **p1 = &cptr;  // 正确：类型匹配
    
    printf("   *p1指向的内容: %s\n", *p1);
    // **p1 = 'c';  // 非法：不能修改const数据
    
    const char *cptr2 = str1;  // str1可以赋值给const char*
    p1 = &cptr2;  // 合法：可以修改p1本身
    printf("   修改p1后指向: %s\n", *p1);
    
    // 2. char *const *p
    // 作用：p是一个指向const指针的指针，该const指针指向char
    printf("\n2. char *const *p 测试：\n");
    char *const ptr2 = str2;  // const指针
    char *const *p2 = &ptr2;
    
    printf("   *p2指向的内容: %s\n", *p2);
    **p2 = 'W';  // 合法：可以修改指向的数据
    printf("   修改数据后: %s\n", *p2);
    
    char *const ptr2_2 = str1;
    // p2 = &ptr2_2;  // 合法：可以修改p2本身
    printf("   修改p2本身成功\n");
    
    // 3. char **const p
    // 作用：p是一个const指针，指向指向char的指针
    printf("\n3. char **const p 测试：\n");
    char *ptr3 = str3;
    char **const p3 = &ptr3;  // p3本身是const
    
    printf("   *p3指向的内容: %s\n", *p3);
    **p3 = 'T';  // 合法：可以修改指向的数据
    printf("   修改数据后: %s\n", *p3);
    
    char *ptr3_2 = str1;
    *p3 = ptr3_2;  // 合法：可以修改指向的指针
    printf("   修改指向的指针后: %s\n", *p3);
    
    // p3 = &ptr3_2;  // 非法：不能修改p3本身
    
    // 额外的演示：不同类型之间的赋值限制
    printf("\n4. 类型转换演示：\n");
    char *p_char = str1;
    const char *p_const_char = cstr;
    
    // p1 = &p_char;  // 非法：char** 不能转换为 const char**
    // 但可以这样做：
    const char **p1_ok = (const char**)&p_char;  // 强制转换，但不推荐
    printf("   强制转换后: %s\n", *p1_ok);
    
    return 0;
}